#include <iostream>
#include <string>

int main() {
    char zeichen = 'A';
    std::string text = "A";

    std::cout << "Zeichen: " << zeichen << std::endl;
    std::cout << "Text: " << text << std::endl;
    std::cout << "Zeichen als Zahl: " << static_cast<int>(zeichen) << std::endl;
    std::cout << "Laenge des Textes: " << text.size() << std::endl;

    return 0;
}

#include <iostream>

int main() {
    double komma = 3.99;
    int abgeschnitten = static_cast<int>(komma);

    int sieben = 7;
    double haelfte = static_cast<double>(sieben) / 2.0;

    std::cout << "komma: " << komma << std::endl;
    std::cout << "abgeschnitten: " << abgeschnitten << std::endl;
    std::cout << "sieben halb: " << haelfte << std::endl;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string eingabe = "42";
    int zahl = std::stoi(eingabe);
    int doppelt = zahl * 2;
    std::string ausgabe = std::to_string(doppelt);

    std::cout << "Eingabe: " << eingabe << std::endl;
    std::cout << "Doppelt: " << ausgabe << std::endl;
    std::cout << "Laenge: " << ausgabe.size() << std::endl;

    return 0;
}

