#include <iostream>

int main() {
    int breite = 0;
    int hoehe = 0;

    std::cout << "Breite in cm: ";
    std::cin >> breite;
    std::cout << "Hoehe in cm: ";
    std::cin >> hoehe;

    int flaeche = breite * hoehe;
    int umfang = 2 * (breite + hoehe);

    std::cout << "Flaeche: " << flaeche << " qcm" << std::endl;
    std::cout << "Umfang: " << umfang << " cm" << std::endl;

    return 0;
}

#include <iostream>
#include <string>

